begin;
do $$begin if current_database()<>'fb_s53_auth' or exists(select 1 from public.hotels where slug not like 'fb-lab-%') then raise exception 'Owned fixtures only';end if;end$$;
create temporary table b4_time_results(label text primary key);
create function pg_temp.b4_time_check(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'B4 temporal: %',label;end if;insert into b4_time_results values(label);end$$;
do $$declare h uuid;outlet uuid:=gen_random_uuid();scope uuid:=gen_random_uuid();begin
 select hotel_id into h from fb_order_private.hotel_settings order by hotel_id limit 1;
 insert into public.hotel_fb_outlets(id,hotel_id,name,type) values(outlet,h,'Temporal fixture','restaurant');
 insert into fb_order_private.availability_scopes(id,hotel_id,outlet_id) values(scope,h,outlet);
 update fb_order_private.hotel_settings set timezone='America/Recife' where hotel_id=h;
 insert into fb_order_private.availability_windows(hotel_id,scope_id,weekday,start_minute,end_minute,next_day) values(h,scope,0,1380,60,true);
 perform pg_temp.b4_time_check(not fb_order_private.scope_available(h,'outlet',outlet,'2026-11-02 01:59:59+00'),'Sunday before exact start');
 perform pg_temp.b4_time_check(fb_order_private.scope_available(h,'outlet',outlet,'2026-11-02 02:00:00+00'),'Sunday exact start inclusive');
 perform pg_temp.b4_time_check(fb_order_private.scope_available(h,'outlet',outlet,'2026-11-02 03:00:00+00'),'Sunday to Monday midnight');
 perform pg_temp.b4_time_check(fb_order_private.scope_available(h,'outlet',outlet,'2026-11-02 03:59:59+00'),'overnight before end');
 perform pg_temp.b4_time_check(not fb_order_private.scope_available(h,'outlet',outlet,'2026-11-02 04:00:00+00'),'exact end exclusive');
 update fb_order_private.availability_scopes set manual_closed=true,closed_until='2026-11-02 03:30+00' where id=scope;
 perform pg_temp.b4_time_check(not fb_order_private.scope_available(h,'outlet',outlet,'2026-11-02 03:29:59+00'),'manual closed');
 perform pg_temp.b4_time_check(fb_order_private.scope_available(h,'outlet',outlet,'2026-11-02 03:30+00'),'automatic reopening exact expiry');
 update fb_order_private.availability_scopes set manual_closed=false where id=scope;
 insert into fb_order_private.availability_exceptions(hotel_id,scope_id,starts_at,ends_at,available) values(h,scope,'2026-11-02 03:10+00','2026-11-02 03:20+00',false);
 perform pg_temp.b4_time_check(not fb_order_private.scope_available(h,'outlet',outlet,'2026-11-02 03:10+00'),'closing exception begins inclusive');
 perform pg_temp.b4_time_check(fb_order_private.scope_available(h,'outlet',outlet,'2026-11-02 03:20+00'),'closing exception ends exclusive');
 delete from fb_order_private.availability_windows where scope_id=scope;
 update fb_order_private.hotel_settings set timezone='Asia/Tokyo' where hotel_id=h;
 insert into fb_order_private.availability_windows(hotel_id,scope_id,weekday,start_minute,end_minute,next_day) values(h,scope,1,540,600,false);
 perform pg_temp.b4_time_check(fb_order_private.scope_available(h,'outlet',outlet,'2026-11-02 00:00+00'),'explicit Tokyo timezone');
 perform pg_temp.b4_time_check(not fb_order_private.scope_available(h,'outlet',outlet,'2026-11-02 01:00+00'),'Tokyo end exclusive');
 delete from fb_order_private.availability_windows where scope_id=scope;
 update fb_order_private.hotel_settings set timezone='America/New_York' where hotel_id=h;
 insert into fb_order_private.availability_windows(hotel_id,scope_id,weekday,start_minute,end_minute,next_day) values(h,scope,0,60,120,false);
 perform pg_temp.b4_time_check(fb_order_private.scope_available(h,'outlet',outlet,'2026-11-01 05:30+00'),'DST ambiguous hour first occurrence');
 perform pg_temp.b4_time_check(fb_order_private.scope_available(h,'outlet',outlet,'2026-11-01 06:30+00'),'DST ambiguous hour second occurrence');
 perform pg_temp.b4_time_check(not fb_order_private.scope_available(h,'outlet',outlet,'2026-03-08 07:00+00'),'DST skipped local hour is not fabricated');
 perform pg_temp.b4_time_check(fb_order_private.scope_available(h,'menu',gen_random_uuid(),'2026-11-01 05:30+00'),'unset child scope inherits permissively; price enforces ancestors');
end$$;
select json_build_object('suite','53_b4_temporal_matrix','passed',(select count(*) from b4_time_results),'failed',0,'rollback',true);
rollback;
